// Reference gate for n4m_linear_sum_assignment, n4m_cluster_jaccard_matrix,
// n4m_random_permutations and n4m_random_multivariate_normal (ABI 2.20) against
// parity/fixtures/cluster_matching_null_v1.json, generated by
// parity/generators/cluster_matching_null_v1.py from NumPy 2.4.6, SciPy 1.18.1,
// scikit-learn 1.9.1 and hdbscan 0.8.44. HDBSCAN on the simulated Gaussian
// data is compared up to label permutation with the stable-tie reference.
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

#include "fixture_parser.hpp"
#include "n4m/n4m.h"

#define REQUIRE(x) do { if (!(x)) throw std::runtime_error(std::string(#x) + " @" + std::to_string(__LINE__)); } while (false)

namespace {
using namespace n4m_testing;

bool close(double got, double want, double tol = 1e-12) {
    if (std::isnan(want)) return std::isnan(got);
    return std::abs(got - want) <= tol * std::max(1.0, std::abs(want));
}

std::vector<int64_t> int_array(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    REQUIRE(s[pos] == '[');
    std::vector<int64_t> out;
    ++pos;
    while (true) {
        skip_ws(s, pos);
        if (s[pos] == ']') break;
        char* tail = nullptr;
        out.push_back(std::strtoll(s.c_str() + pos, &tail, 10));
        pos = static_cast<size_t>(tail - s.c_str());
        skip_ws(s, pos);
        if (s[pos] == ',') ++pos;
    }
    return out;
}

// All integers of a possibly nested array, in order.
std::vector<int64_t> flat_int_array(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    REQUIRE(s[pos] == '[');
    std::vector<int64_t> out;
    int depth = 0;
    do {
        const char c = s[pos];
        if (c == '[') { ++depth; ++pos; }
        else if (c == ']') { --depth; ++pos; }
        else if (c == '-' || (c >= '0' && c <= '9')) {
            char* tail = nullptr;
            out.push_back(std::strtoll(s.c_str() + pos, &tail, 10));
            pos = static_cast<size_t>(tail - s.c_str());
        } else { ++pos; }
    } while (depth > 0);
    return out;
}

std::vector<double> hex_array(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    std::vector<double> out;
    parse_hex_double_array(s, pos, out);
    return out;
}

std::string text(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    return parse_string(s, pos);
}

int64_t integer(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    return parse_int64(s, find_value_for_key(s, key, lo, hi));
}

uint64_t seed_of(const std::string& s, size_t lo, size_t hi) {
    return std::strtoull(text(s, "seed", lo, hi).c_str(), nullptr, 10);
}

void assignment_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto rows = integer(s, "rows", lo, hi), cols = integer(s, "cols", lo, hi);
    const auto maximize = static_cast<int32_t>(integer(s, "maximize", lo, hi));
    auto cost = hex_array(s, "cost_hex", lo, hi);
    const auto k = static_cast<size_t>(std::min(rows, cols));
    std::vector<int64_t> r(k, -7), c(k, -7);
    int64_t assigned = -1;
    n4m_matrix_view_t C{};
    REQUIRE(n4m_matrix_view_init_rowmajor(&C, cost.data(), rows, cols, N4M_DTYPE_F64) == N4M_OK);
    const auto st = n4m_linear_sum_assignment(ctx, &C, maximize, r.data(), c.data(), &assigned);
    const size_t error_pos = find_value_for_key(s, "error", lo, hi);
    if (s.compare(error_pos, 4, "null") != 0) {
        size_t pos = error_pos;
        const auto error = parse_string(s, pos);
        REQUIRE(st == (error == "infeasible" ? N4M_ERR_NUMERICAL_FAILURE : N4M_ERR_INVALID_ARGUMENT));
        return;
    }
    REQUIRE(st == N4M_OK && assigned == static_cast<int64_t>(k));
    REQUIRE(r == int_array(s, "row_ind", lo, hi));
    REQUIRE(c == int_array(s, "col_ind", lo, hi));
    double total = 0.0;
    for (size_t i = 0; i < k; ++i)
        total += cost[static_cast<size_t>(r[i] * cols + c[i])];
    REQUIRE(close(total, hex_array(s, "total_hex", lo, hi)[0]));

    // Column-major storage of the same matrix gives the same assignment.
    std::vector<double> colmajor(cost.size());
    for (int64_t i = 0; i < rows; ++i) for (int64_t j = 0; j < cols; ++j)
        colmajor[static_cast<size_t>(j * rows + i)] = cost[static_cast<size_t>(i * cols + j)];
    n4m_matrix_view_t T{};
    REQUIRE(n4m_matrix_view_init_colmajor(&T, colmajor.data(), rows, cols, N4M_DTYPE_F64) == N4M_OK);
    std::vector<int64_t> r2(k), c2(k);
    REQUIRE(n4m_linear_sum_assignment(ctx, &T, maximize, r2.data(), c2.data(), &assigned) == N4M_OK);
    REQUIRE(r2 == r && c2 == c);
}

void jaccard_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto a = int_array(s, "labels_a", lo, hi), b = int_array(s, "labels_b", lo, hi);
    const auto ka = integer(s, "n_clusters_a", lo, hi), kb = integer(s, "n_clusters_b", lo, hi);
    const auto cells = static_cast<size_t>(ka * kb);
    std::vector<double> jac(cells);
    std::vector<int64_t> inter(cells), sa(static_cast<size_t>(ka)), sb(static_cast<size_t>(kb));
    REQUIRE(n4m_cluster_jaccard_matrix(ctx, a.data(), b.data(), static_cast<int64_t>(a.size()), ka, kb,
                                       jac.data(), inter.data(), sa.data(), sb.data()) == N4M_OK);
    REQUIRE(inter == int_array(s, "intersections", lo, hi));
    REQUIRE(sa == int_array(s, "sizes_a", lo, hi) && sb == int_array(s, "sizes_b", lo, hi));
    const auto want = hex_array(s, "jaccard_hex", lo, hi);
    for (size_t i = 0; i < cells; ++i) REQUIRE(close(jac[i], want[i], 0.0));
}

void normal_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto d = integer(s, "d", lo, hi), n = integer(s, "n", lo, hi);
    auto mean = hex_array(s, "mean_hex", lo, hi), cov = hex_array(s, "cov_hex", lo, hi);
    const auto want = hex_array(s, "draws_hex", lo, hi);
    n4m_matrix_view_t C{};
    REQUIRE(n4m_matrix_view_init_rowmajor(&C, cov.data(), d, d, N4M_DTYPE_F64) == N4M_OK);
    std::vector<double> out(static_cast<size_t>(n * d));
    REQUIRE(n4m_random_multivariate_normal(ctx, seed_of(s, lo, hi), mean.data(), &C, n, out.data()) == N4M_OK);
    REQUIRE(want.size() == out.size());
    for (size_t i = 0; i < out.size(); ++i) REQUIRE(close(out[i], want[i]));
    // Only the lower triangle is read.
    for (int64_t i = 0; i < d; ++i) for (int64_t j = i + 1; j < d; ++j)
        cov[static_cast<size_t>(i * d + j)] = std::numeric_limits<double>::quiet_NaN();
    std::vector<double> again(out.size());
    REQUIRE(n4m_random_multivariate_normal(ctx, seed_of(s, lo, hi), mean.data(), &C, n, again.data()) == N4M_OK);
    REQUIRE(again == out);
}

void permutations_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto n = integer(s, "n", lo, hi), b = integer(s, "n_permutations", lo, hi);
    std::vector<int64_t> out(static_cast<size_t>(n * b) + 1, -9);
    REQUIRE(n4m_random_permutations(ctx, seed_of(s, lo, hi), n, b, out.data()) == N4M_OK);
    REQUIRE(out.back() == -9);
    out.pop_back();
    REQUIRE(out == flat_int_array(s, "draws", lo, hi));
}

// Labels up to a bijection with identical noise.
void same_partition(const std::vector<int64_t>& got, const std::vector<int64_t>& want) {
    REQUIRE(got.size() == want.size());
    std::map<int64_t, int64_t> forward, backward;
    for (size_t i = 0; i < got.size(); ++i) {
        REQUIRE((got[i] < 0) == (want[i] < 0));
        if (got[i] < 0) continue;
        REQUIRE(forward.emplace(got[i], want[i]).first->second == want[i]);
        REQUIRE(backward.emplace(want[i], got[i]).first->second == got[i]);
    }
}

// Squared differences that overflow or underflow (review 2026-10-13: the
// global 2^k scaling turned [0, 1, 3, 10, 11, 14, 1e200] into all noise).
void multiscale_hdbscan_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto rows = integer(s, "rows", lo, hi), cols = integer(s, "cols", lo, hi);
    auto x = hex_array(s, "input_hex", lo, hi);
    n4m_matrix_view_t X{};
    REQUIRE(n4m_matrix_view_init_rowmajor(&X, x.data(), rows, cols, N4M_DTYPE_F64) == N4M_OK);
    const auto un = static_cast<size_t>(rows);
    std::vector<int64_t> labels(un), parent(un), size(un), label(un);
    std::vector<double> membership(un), outlier(un), persistence(un), birth(un), death(un), stab(un);
    int64_t clusters = 0, nodes = 0;
    REQUIRE(n4m_cluster_hdbscan(ctx, &X, integer(s, "min_cluster_size", lo, hi),
                                integer(s, "min_samples", lo, hi), 0, 0, labels.data(),
                                membership.data(), outlier.data(), &clusters, persistence.data(),
                                &nodes, parent.data(), size.data(), label.data(), birth.data(),
                                death.data(), stab.data()) == N4M_OK);
    same_partition(labels, int_array(s, "labels", lo, hi));
    const auto want = hex_array(s, "membership_hex", lo, hi);
    for (size_t i = 0; i < un; ++i) REQUIRE(close(membership[i], want[i]));
    std::printf("multiscale hdbscan %-30s clusters=%lld ok\n", text(s, "name", lo, hi).c_str(),
                static_cast<long long>(clusters));
}

// Large-n ARI against exact-integer scikit-learn (no cancelled products).
void ari_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto n = integer(s, "n", lo, hi), ka = integer(s, "ka", lo, hi);
    const auto kb = integer(s, "kb", lo, hi), shift = integer(s, "shift", lo, hi);
    std::vector<int64_t> a(static_cast<size_t>(n)), b(a.size());
    for (int64_t i = 0; i < n; ++i) {
        a[static_cast<size_t>(i)] = i % ka;
        b[static_cast<size_t>(i)] = (i / ka + shift * (i % 3)) % kb;
    }
    double got = 0.0;
    REQUIRE(n4m_preflight_adjusted_rand_index(ctx, a.data(), b.data(), n, &got) == N4M_OK);
    const double want = hex_array(s, "ari_hex", lo, hi)[0];
    REQUIRE(std::fabs(got - want) <= 1e-14 * std::fabs(want));
}

void gaussian_hdbscan_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    const auto d = integer(s, "d", lo, hi), n = integer(s, "n", lo, hi);
    auto cov = hex_array(s, "cov_hex", lo, hi);
    std::vector<double> mean(static_cast<size_t>(d), 0.0), x(static_cast<size_t>(n * d));
    n4m_matrix_view_t C{}, X{};
    REQUIRE(n4m_matrix_view_init_rowmajor(&C, cov.data(), d, d, N4M_DTYPE_F64) == N4M_OK);
    REQUIRE(n4m_random_multivariate_normal(ctx, seed_of(s, lo, hi), mean.data(), &C, n, x.data()) == N4M_OK);
    REQUIRE(n4m_matrix_view_init_rowmajor(&X, x.data(), n, d, N4M_DTYPE_F64) == N4M_OK);
    const auto un = static_cast<size_t>(n);
    std::vector<int64_t> labels(un), parent(un), size(un), label(un);
    std::vector<double> membership(un), outlier(un), persistence(un), birth(un), death(un), stab(un);
    int64_t clusters = 0, nodes = 0;
    REQUIRE(n4m_cluster_hdbscan(ctx, &X, integer(s, "min_cluster_size", lo, hi),
                                integer(s, "min_samples", lo, hi), 0, 0, labels.data(),
                                membership.data(), outlier.data(), &clusters, persistence.data(),
                                &nodes, parent.data(), size.data(), label.data(), birth.data(),
                                death.data(), stab.data()) == N4M_OK);
    REQUIRE(clusters == integer(s, "n_clusters", lo, hi));
    same_partition(labels, int_array(s, "labels", lo, hi));
    std::printf("gaussian hdbscan %-32s clusters=%lld ok\n", text(s, "name", lo, hi).c_str(),
                static_cast<long long>(clusters));
}
}  // namespace

int main() {
    n4m_context_t* ctx = nullptr;
    try {
        REQUIRE(n4m_context_create(&ctx) == N4M_OK);
        const std::string s = slurp(std::string(N4M_PARITY_FIXTURE_DIR) + "/cluster_matching_null_v1.json");
        REQUIRE(s.find("\"n4m_cluster_matching_null_v1\"") != std::string::npos);
        const auto [lo, hi] = find_cases_array(s);
        std::map<std::string, int> seen;
        for (const auto& [a, b] : list_case_object_spans(s, lo, hi)) {
            const auto kind = text(s, "kind", a, b);
            ++seen[kind];
            if (kind == "assignment") assignment_case(ctx, s, a, b);
            else if (kind == "jaccard") jaccard_case(ctx, s, a, b);
            else if (kind == "normal") normal_case(ctx, s, a, b);
            else if (kind == "permutations") permutations_case(ctx, s, a, b);
            else if (kind == "gaussian_hdbscan") gaussian_hdbscan_case(ctx, s, a, b);
            else if (kind == "multiscale_hdbscan") multiscale_hdbscan_case(ctx, s, a, b);
            else if (kind == "ari") ari_case(ctx, s, a, b);
            else REQUIRE(false);
        }
        REQUIRE(seen["assignment"] == 12 && seen["jaccard"] == 4 && seen["normal"] == 4 && seen["permutations"] == 4 &&
                seen["gaussian_hdbscan"] == 3 && seen["multiscale_hdbscan"] == 5 && seen["ari"] == 3);

        // Argument validation.
        double cost[4] = {1, 2, 3, 4};
        int64_t r[2], c[2], assigned = 0;
        n4m_matrix_view_t C{};
        REQUIRE(n4m_matrix_view_init_rowmajor(&C, cost, 2, 2, N4M_DTYPE_F64) == N4M_OK);
        REQUIRE(n4m_linear_sum_assignment(ctx, &C, 2, r, c, &assigned) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(n4m_linear_sum_assignment(ctx, &C, 0, nullptr, c, &assigned) == N4M_ERR_NULL_POINTER);
        REQUIRE(n4m_linear_sum_assignment(ctx, &C, 0, r, c, &assigned) == N4M_OK);
        REQUIRE(assigned == 2 && r[0] == 0 && c[0] == 0 && r[1] == 1 && c[1] == 1);

        const int64_t la[3] = {0, 1, 2}, lb[3] = {0, -1, 0};
        double jac[2];
        int64_t inter[2], sa[2], sb[1];
        REQUIRE(n4m_cluster_jaccard_matrix(ctx, la, lb, 3, 2, 1, jac, inter, sa, sb) ==
                N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(n4m_cluster_jaccard_matrix(ctx, la, lb, -1, 2, 1, jac, inter, sa, sb) ==
                N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(n4m_cluster_jaccard_matrix(ctx, la, lb, 2, 2, 1, jac, inter, sa, sb) == N4M_OK);
        REQUIRE(inter[0] == 1 && inter[1] == 0 && close(jac[0], 1.0) && close(jac[1], 0.0));

        double mean[2] = {0, 0}, out[4];
        double singular[4] = {1, 1, 1, 1}, indefinite[4] = {1, 0, 0, -1};
        n4m_matrix_view_t S{}, I{};
        REQUIRE(n4m_matrix_view_init_rowmajor(&S, singular, 2, 2, N4M_DTYPE_F64) == N4M_OK);
        REQUIRE(n4m_matrix_view_init_rowmajor(&I, indefinite, 2, 2, N4M_DTYPE_F64) == N4M_OK);
        REQUIRE(n4m_random_multivariate_normal(ctx, 1, mean, &S, 2, out) == N4M_ERR_NUMERICAL_FAILURE);
        REQUIRE(n4m_random_multivariate_normal(ctx, 1, mean, &I, 2, out) == N4M_ERR_NUMERICAL_FAILURE);
        REQUIRE(n4m_random_multivariate_normal(ctx, 1, mean, &C, -1, out) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(n4m_random_multivariate_normal(ctx, 1, nullptr, &C, 2, out) == N4M_ERR_NULL_POINTER);
        n4m_matrix_view_t W{};
        REQUIRE(n4m_matrix_view_init_rowmajor(&W, cost, 1, 2, N4M_DTYPE_F64) == N4M_OK);
        REQUIRE(n4m_random_multivariate_normal(ctx, 1, mean, &W, 2, out) == N4M_ERR_INVALID_ARGUMENT);
        int64_t perm[2];
        REQUIRE(n4m_random_permutations(ctx, 1, -1, 1, perm) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(n4m_random_permutations(ctx, 1, 2, 1, nullptr) == N4M_ERR_NULL_POINTER);
        REQUIRE(n4m_random_permutations(ctx, 1, 100000, 100000, perm) == N4M_ERR_UNSUPPORTED);
        // Review 2026-10-13 P0: a 65536 x 65536 overlapping view with n = 0
        // bypassed the n*d*d budget and, on WASM32, d*d wrapped to 0 before
        // the Cholesky factor was written. Limits are now checked first.
        {
            std::vector<double> backing(131071, 1.0), big_mean(65536, 0.0);
            n4m_matrix_view_t O{};
            REQUIRE(n4m_matrix_view_init_strided(&O, backing.data(), 65536, 65536, 1, 1,
                                                 N4M_DTYPE_F64) == N4M_OK);
            REQUIRE(n4m_random_multivariate_normal(ctx, 1, big_mean.data(), &O, 0, nullptr) ==
                    N4M_ERR_UNSUPPORTED);
            // d^3/6 above 2.5e9 is refused even though d*d fits.
            n4m_matrix_view_t Q{};
            REQUIRE(n4m_matrix_view_init_strided(&Q, backing.data(), 2500, 2500, 1, 1,
                                                 N4M_DTYPE_F64) == N4M_OK);
            REQUIRE(n4m_random_multivariate_normal(ctx, 1, big_mean.data(), &Q, 0, nullptr) ==
                    N4M_ERR_UNSUPPORTED);
            // Zero draws of a valid covariance succeed without writing.
            double identity[4] = {1, 0, 0, 1};
            n4m_matrix_view_t E{};
            REQUIRE(n4m_matrix_view_init_rowmajor(&E, identity, 2, 2, N4M_DTYPE_F64) == N4M_OK);
            REQUIRE(n4m_random_multivariate_normal(ctx, 1, mean, &E, 0, nullptr) == N4M_OK);
        }
        mean[1] = std::numeric_limits<double>::infinity();
        REQUIRE(n4m_random_multivariate_normal(ctx, 1, mean, &C, 2, out) == N4M_ERR_INVALID_ARGUMENT);
        n4m_context_destroy(ctx);
        std::puts("n4m_cluster_matching_null_tests: ok");
        return 0;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "n4m_cluster_matching_null_tests failed: %s\n", e.what());
        if (ctx) n4m_context_destroy(ctx);
        return 1;
    }
}
